const pad=n=>String(n).padStart(2,'0');
function shiftDate(d,offset){const dt=new Date(d+'T12:00:00');dt.setDate(dt.getDate()+offset);return [dt.getFullYear(),pad(dt.getMonth()+1),pad(dt.getDate())].join('-')}
function dateLabel(d){const parts=d.split('-');let w=['日','一','二','三','四','五','六'][new Date(d+'T12:00:00').getDay()];return `${Number(parts[1])} 月 ${Number(parts[2])} 日 · 星期${w}`}
function tagsHTML(ts){return (ts||[]).map(t=>`<span class="tag">#${esc(t)}</span>`).join('')}
function taskBy(id){return tasks.find(t=>t.id===id)}function noteBy(id){return notes.find(n=>n.id===id)}
function btn(label,action,cl=''){return `<button type="button" class="btn ${cl}" data-action="${action}">${label}</button>`}
function navButton(id,label,icon){return `<button class="navbtn ${state.view===id?'active':''}" data-nav="${id}">${ic(icon)} ${label}</button>`}
function sidebar(){const labels=['架构设计','Flink','Doris','POC','复盘','工作'];return `<aside class="sidebar"><div class="brand"><div class="brand-icon">啪</div><div><h1>啪嗒 <span style="font-weight:400;color:#a5ada4;font-size:10px">PATA</span></h1><p>记下一点，完成一件</p></div></div><nav class="sidebar-nav">${navButton('today','Today','sun')}${navButton('tasks','Tasks','tasks')}${navButton('notes','Notes','note')}</nav><div class="sidebar-sep"></div><div class="sidetitle">标签 · LABELS</div><div class="taglist">${labels.map(t=>`<button class="tagbtn ${state.view==='tag'&&state.activeTag===t?'active':''}" data-tag="${esc(t)}"># ${esc(t)}</button>`).join('')}</div><div class="sidefooter"><span class="tiny-dot"></span>本地 Markdown 工作空间<br/>Less is More · 设计原型</div></aside>`}
function topbar(){let cur=state.view==='tag'?'标签 / #'+state.activeTag:state.view==='notes'?'Notes':state.view==='tasks'?'Tasks':'Today';let sub=state.detail?(state.view==='notes'?(noteBy(state.detail)?.title||'新笔记'):(taskBy(state.detail)?.title||'')):'';return `<header class="topbar"><div class="crumb"><span class="home">工作空间</span><span>/</span><span>${esc(cur)}</span>${sub?`<span>/</span><span>${esc(sub)}</span>`:''}</div><div class="top-actions"><span class="demo-flag"><span class="tiny-dot"></span>仅 UI 原型</span><button class="iconbutton" title="全局搜索" data-action="search">${ic('search')}</button><span class="kbd">⌘ K</span></div></header>`}
function taskRow(t,from){return `<div class="task-row"><button class="check ${t.status==='done'?'done':''}" aria-label="切换完成状态" data-check="${t.id}">${t.status==='done'?ic('check'):''}</button><div class="task-text" data-open-task="${t.id}"><div class="title ${t.status==='done'?'completed':''}">${esc(t.title)}</div><div class="sub">${esc(t.tags.map(x=>'#'+x).join(' · '))}${t.due?' · 截止 '+t.due.slice(5).replace('-','/') :''}</div></div><span class="priority ${t.priority}">${t.priority.toUpperCase()}</span>${from==='today'?`<button class="iconbutton" title="从今日移出" data-remove-plan="${t.id}">${ic('ellipsis')}</button>`:''}</div>`}
function today(){let ids=plans[state.date]||[];let items=ids.map(taskBy).filter(Boolean), entries=[...memos.filter(m=>m.date===state.date).map(m=>({...m,kind:'memo'})),...events.filter(e=>e.date===state.date).map(e=>({...e,kind:'event'}))].sort((a,b)=>b.time.localeCompare(a.time));return `<div class="main"><div class="page-head"><div><div class="eyebrow">YOUR DAILY SPACE</div><h1 class="page-title">Today <span style="color:#cad7c9;font-weight:400">/</span> 今天</h1><p class="page-sub">${dateLabel(state.date)} · 给重要的事留一点空间</p></div><div class="head-tools"><button class="btn small" data-action="prev-day">${ic('left')}</button><button class="btn small" data-action="next-day">${ic('right')}</button>${btn('回到今天','reset-day','small muted')}</div></div><section class="section"><div class="section-heading"><h2 class="section-title">今日计划 <span class="section-count">${items.filter(t=>t.status==='done').length} / ${items.length}</span></h2>${btn(ic('plus')+' 添加任务','pick-task','small')}</div><div class="task-panel">${items.length?items.map(t=>taskRow(t,'today')).join(''):'<div class="empty">还没有安排任务。今天可以从一件小事开始。</div>'}</div><p class="hint" style="margin-top:11px">仅安排今天要推进的任务，不改变任务的截止日期。</p></section><div class="thin-sep"></div><section class="section"><div class="section-heading"><h2 class="section-title">今日记录 <span class="section-count">${entries.length}</span></h2><span class="hint">自动聚合 · 无需写日报</span></div><div class="timeline">${entries.length?entries.map(e=>`<div class="timeline-item ${e.kind==='event'?'event':''}"><div class="timeline-date">${esc(e.time)} ${e.kind==='event'?'· 任务事件':'· '+(e.taskId?'任务评论':'独立 Memo')}</div><div class="memo-card"><div class="memo-meta">${ic(e.kind==='event'?'check':'memo')} <span class="source">${e.taskId?`<a href="#" data-open-task="${e.taskId}">${esc(taskBy(e.taskId)?.title||'已删除的任务')}</a>`:'随手记录'}</span></div><div class="memo-text">${esc(e.text)}</div></div></div>`).join(''):'<div class="empty">今天还没有记录。</div>'}</div><div class="compose"><textarea id="quickMemo" placeholder="随手记下工作进展、问题或想法…"></textarea><div class="compose-footer"><span class="hint">独立 Memo · 不需要标题或标签</span>${btn('记录一下','add-quick-memo','small primary')}</div></div></section></div>`}
function tasksList(){let filtered=tasks.filter(t=>(state.taskFilter==='all'||t.status===state.taskFilter)&&t.title.toLowerCase().includes(state.taskQuery.toLowerCase()));return `<div class="main"><div class="page-head"><div><div class="eyebrow">THE WORK POOL</div><h1 class="page-title">Tasks</h1><p class="page-sub">所有工作都在这里，跨天持续推进。</p></div>${btn(ic('plus')+' 新建任务','new-task','primary')}</div><div class="searchbar">${ic('search')}<input id="taskSearch" value="${esc(state.taskQuery)}" placeholder="查找任务…" aria-label="查找任务"/></div><div class="filters">${[['all','全部'],['todo','待办'],['doing','进行中'],['done','已完成']].map(([key,val])=>`<button class="chip ${state.taskFilter===key?'selected':''}" data-task-filter="${key}">${val}</button>`).join('')}</div><div class="section-heading"><h2 class="section-title">任务列表 <span class="section-count">${filtered.length}</span></h2><span class="hint">点击任务查看进展与 Memo</span></div><div class="task-panel">${filtered.length?filtered.map(t=>taskRow(t)).join(''):'<div class="empty">没有找到符合条件的任务。</div>'}</div></div>`}
function taskDetail(){const t=taskBy(state.detail);if(!t)return tasksList();const related=memos.filter(m=>m.taskId===t.id).sort((a,b)=>b.date.localeCompare(a.date)||b.time.localeCompare(a.time));return `<div class="main"><div class="detail-article"><button class="back" data-action="back-tasks">${ic('left')} 返回任务列表</button><div class="eyebrow">TASK DETAILS</div><h1 class="article-title">${esc(t.title)}</h1><div class="task-detail-info"><span class="detail-prop">${ic('tasks')} 状态 <strong>${{todo:'待办',doing:'进行中',done:'已完成'}[t.status]}</strong></span><span class="detail-prop">优先级 <strong>${t.priority.toUpperCase()}</strong></span>${t.due?`<span class="detail-prop">${ic('calendar')} 截止 <strong>${t.due}</strong></span>`:''}</div><div class="article-meta">${tagsHTML(t.tags)}</div><div class="section-heading"><h2 class="section-title">任务说明</h2>${t.note?`<button class="section-link" data-open-note="${t.note}">${ic('file')} 查看关联笔记</button>`:''}</div><div class="detail-desc">${esc(t.desc)}</div><div class="thin-sep"></div><div class="section-heading"><h2 class="section-title">进展记录 <span class="section-count">${related.length}</span></h2></div>${related.map(m=>`<div class="memo-card"><div class="memo-meta">${ic('memo')} ${m.date} · ${m.time}</div><div class="memo-text">${esc(m.text)}</div></div>`).join('')||'<div class="empty">暂无进展记录。</div>'}<div class="compose"><textarea id="taskMemo" placeholder="记录进展、结论或阻塞…"></textarea><div class="compose-footer"><span class="hint">自动关联此任务</span>${btn('添加记录','add-task-memo','small primary')}</div></div></div></div>`}
function notesList(){let q=state.notesQuery.trim().toLowerCase();let found=notes.filter(n=>(n.title+n.excerpt+n.tags.join(' ')).toLowerCase().includes(q));return `<div class="main content-narrow"><div class="page-head"><div><div class="eyebrow">YOUR KNOWLEDGE SPACE</div><h1 class="page-title">Notes</h1><p class="page-sub">记录值得留下的东西，打开一篇，专注写作。</p></div>${btn(ic('plus')+' 新建笔记','new-note','primary')}</div><div class="searchbar">${ic('search')}<input id="noteSearch" value="${esc(state.notesQuery)}" placeholder="搜索标题、内容、标签…" aria-label="搜索笔记"/></div><div class="section-heading" style="margin-top:29px"><h2 class="section-title">最近编辑 <span class="section-count">${found.length}</span></h2><span class="hint">单列内容浏览</span></div><div class="notes-stack">${found.length?found.map(n=>`<div class="note-card" data-open-note="${n.id}"><h3 class="note-heading">${esc(n.title)}</h3><p class="note-excerpt">${esc(n.excerpt)}</p><div class="card-bottom"><div class="card-tags">${tagsHTML(n.tags)}</div><span class="date">${esc(n.modified)}</span></div></div>`).join(''):'<div class="empty">没有找到相关笔记。</div>'}</div></div>`}
function basicMarkdown(md){let lines=String(md).split('\n'),out=[],list=false,blockquote=false;function close(){if(list){out.push('</ul>');list=false}if(blockquote){out.push('</blockquote>');blockquote=false}}function fmt(s){return esc(s).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')};for(const line of lines){if(/^# /.test(line)){close();out.push(`<h1>${fmt(line.slice(2))}</h1>`)}else if(/^## /.test(line)){close();out.push(`<h2>${fmt(line.slice(3))}</h2>`)}else if(/^- /.test(line)){if(!list){close();out.push('<ul>');list=true}out.push(`<li>${fmt(line.slice(2))}</li>`)}else if(/^> /.test(line)){if(!blockquote){close();out.push('<blockquote>');blockquote=true}out.push(`<p>${fmt(line.slice(2))}</p>`)}else if(line.trim()){close();out.push(`<p>${fmt(line)}</p>`)}else{close()}}close();return out.join('')}
function noteDetail(){const n=noteBy(state.detail);if(!n)return notesList();return `<div class="main"><div class="detail-article"><div class="article-top"><button class="back" data-action="back-notes">${ic('left')} 返回笔记列表</button>${state.isEditing?btn('保存修改','save-note','small primary'):btn(ic('note')+' 编辑正文','edit-note','small')}</div><div class="eyebrow">MARKDOWN NOTE</div>${state.isEditing?`<input class="article-title-input" id="editNoteTitle" value="${esc(n.title)}"/>`:`<h1 class="article-title">${esc(n.title)}</h1>`}<div class="article-meta">${tagsHTML(n.tags)}<span class="date">${esc(n.modified)} 修改</span></div>${state.isEditing?`<textarea class="article-editor" id="editNoteBody">${esc(n.body)}</textarea><p class="hint">原型中仅模拟 Markdown 源码编辑；正式 App 计划使用 Vditor。</p>`:`<div class="article-body">${basicMarkdown(n.body.split('\n')[0]?.trim()==='# '+n.title?n.body.split('\n').slice(1).join('\n'):n.body)}</div>`}</div></div>`}
function hasTag(entity,tag){if(entity.tags.includes(tag))return true;if(entity.taskId){const t=taskBy(entity.taskId);return !!t&&t.tags.includes(tag)}return false}
function tagView(){let tag=state.activeTag,ts=tasks.filter(t=>hasTag(t,tag)),ns=notes.filter(n=>hasTag(n,tag)),ms=memos.filter(m=>hasTag(m,tag));return `<div class="main content-narrow"><div class="page-head"><div><div class="eyebrow">A TOPIC, ALL ITS WORK</div><h1 class="page-title"># ${esc(tag)}</h1><p class="page-sub">同一个主题下，任务、笔记和记录自然关联。</p></div></div>${sectionResults('任务',ts.map(t=>`<div class="result-row" data-open-task="${t.id}">${ic('tasks')}<div class="result-main"><p class="result-title">${esc(t.title)}</p><p class="result-sub">${t.status==='done'?'已完成':'进行中 / 待办'} · ${t.priority.toUpperCase()}</p></div>${ic('right')}</div>`))}${sectionResults('笔记',ns.map(n=>`<div class="result-row" data-open-note="${n.id}">${ic('note')}<div class="result-main"><p class="result-title">${esc(n.title)}</p><p class="result-sub">${esc(n.excerpt)}</p></div>${ic('right')}</div>`))}${sectionResults('记录',ms.map(m=>`<div class="memo-card"><div class="memo-meta">${ic('memo')} ${m.date} · ${m.time}${m.taskId?' · '+esc(taskBy(m.taskId)?.title||'任务'):''}</div><div class="memo-text">${esc(m.text)}</div></div>`))}</div>`}
function sectionResults(label,html){return `<section><div class="group-head"><span class="group-title">${label}</span><span class="section-count">${html.length}</span></div><div class="group-list">${html.length?html.join(''):'<div class="empty" style="padding:18px">暂无相关内容</div>'}</div></section>`}
function modal(){if(!state.modal)return '';let content='';if(state.modal==='pick-task'){const ids=plans[state.date]||[],avail=tasks.filter(t=>!ids.includes(t.id));content=`<h3>添加到今日计划</h3><p class="hint">选择已有任务，不会复制任务或修改截止日期。</p><div class="modal-options">${avail.length?avail.map(t=>`<button class="pickrow" data-pick="${t.id}"><span>${esc(t.title)}</span><span style="color:#9fa89d">${t.priority.toUpperCase()}</span></button>`).join(''):'<div class="empty">所有任务已添加到这一天。</div>'}</div>`}else if(state.modal==='new-task'){content=`<h3>新建任务</h3><input autofocus id="newTaskInput" placeholder="任务名称"/><p class="hint">直接进入统一任务池，不需要项目或 Inbox。</p><div style="display:flex;justify-content:flex-end;margin-top:18px">${btn('创建任务','create-task','small primary')}</div>`}else if(state.modal==='search'){content=`<h3>搜索所有内容</h3><input autofocus id="globalSearchInput" value="${esc(state.search)}" placeholder="搜索 Task / Note / Memo"/><div class="modal-options">${searchResults()}</div>`}return `<div class="modal-backdrop" data-close-modal="1"><div class="modal" role="dialog" aria-modal="true">${content}</div></div>`}
function searchResults(){const q=state.search.trim().toLowerCase();if(!q)return '<div class="empty">输入关键词，跨类型查找本地内容。</div>';let output=[...tasks.filter(t=>(t.title+t.desc+t.tags.join(' ')).toLowerCase().includes(q)).map(t=>`<button class="pickrow" data-open-task="${t.id}">◻ ${esc(t.title)} <span>Task</span></button>`),...notes.filter(n=>(n.title+n.body+n.tags.join(' ')).toLowerCase().includes(q)).map(n=>`<button class="pickrow" data-open-note="${n.id}">▤ ${esc(n.title)} <span>Note</span></button>`),...memos.filter(m=>m.text.toLowerCase().includes(q)).map(m=>`<button class="pickrow" data-memo-result="${m.id}">✎ ${esc(m.text.slice(0,33))} <span>Memo</span></button>`)];return output.join('')||'<div class="empty">没有搜索结果。</div>'}
function render(){document.querySelector('#app').innerHTML=`<div class="shell">${sidebar()}<div class="workspace">${topbar()}${state.view==='today'?today():state.view==='tasks'?(state.detail?taskDetail():tasksList()):state.view==='notes'?(state.detail?noteDetail():notesList()):tagView()}</div></div>${modal()}`}
function navigation(v){state.view=v;state.detail=null;state.isEditing=false;state.modal=null;render()}
function createMemo(text,taskId){const trimmed=text.trim();if(!trimmed)return;let d=state.date;let dt=new Date();let time=pad(dt.getHours())+':'+pad(dt.getMinutes());memos.unshift({id:'m'+Date.now(),date:d,time,taskId:taskId||null,text:trimmed,tags:[]});render()}
document.addEventListener('click',e=>{const x=e.target.closest('[data-nav],[data-tag],[data-action],[data-check],[data-open-task],[data-open-note],[data-task-filter],[data-pick],[data-remove-plan],[data-close-modal],[data-memo-result]');if(!x)return;if(x.hasAttribute('data-close-modal')&&e.target===x){state.modal=null;render();return}if(x.dataset.nav){navigation(x.dataset.nav);return}if(x.dataset.tag){state.activeTag=x.dataset.tag;navigation('tag');state.activeTag=x.dataset.tag;render();return}if(x.dataset.openTask){state.view='tasks';state.detail=x.dataset.openTask;state.modal=null;render();return}if(x.dataset.openNote){state.view='notes';state.detail=x.dataset.openNote;state.isEditing=false;state.modal=null;render();return}if(x.dataset.taskFilter){state.taskFilter=x.dataset.taskFilter;render();return}if(x.dataset.check){let t=taskBy(x.dataset.check);t.status=t.status==='done'?'doing':'done';let time=pad(new Date().getHours())+':'+pad(new Date().getMinutes());events.unshift({date:state.date,time,taskId:t.id,text:(t.status==='done'?'完成任务：':'重新打开任务：')+t.title});render();return}if(x.dataset.removePlan){plans[state.date]=(plans[state.date]||[]).filter(i=>i!==x.dataset.removePlan);render();return}if(x.dataset.pick){plans[state.date]=plans[state.date]||[];if(!plans[state.date].includes(x.dataset.pick))plans[state.date].push(x.dataset.pick);state.modal=null;render();return}if(x.dataset.memoResult){let m=memos.find(m=>m.id===x.dataset.memoResult);state.modal=null;if(m?.taskId){state.view='tasks';state.detail=m.taskId}else{state.view='today';state.date=m?.date||state.date}render();return}let action=x.dataset.action;if(!action)return;if(action==='prev-day')state.date=shiftDate(state.date,-1);if(action==='next-day')state.date=shiftDate(state.date,1);if(action==='reset-day')state.date='2026-10-11';if(action==='pick-task'||action==='new-task'||action==='search')state.modal=action;if(action==='back-tasks'){state.detail=null;state.view='tasks'}if(action==='back-notes'){state.detail=null;state.isEditing=false;state.view='notes'}if(action==='edit-note')state.isEditing=true;if(action==='new-note'){let id='n'+Date.now();notes.unshift({id,title:'未命名笔记',tags:[],modified:'刚刚',excerpt:'一篇新的 Markdown 笔记',body:'# 未命名笔记\n\n开始写作…'});state.detail=id;state.view='notes';state.isEditing=true}if(action==='save-note'){let n=noteBy(state.detail);n.title=document.querySelector('#editNoteTitle').value.trim()||'未命名笔记';n.body=document.querySelector('#editNoteBody').value;n.modified='刚刚';n.excerpt=n.body.replace(/[#*`>]/g,'').replace(/\n/g,' ').trim().slice(0,85);state.isEditing=false}if(action==='add-quick-memo'){createMemo(document.querySelector('#quickMemo')?.value,null);return}if(action==='add-task-memo'){createMemo(document.querySelector('#taskMemo')?.value,state.detail);return}if(action==='create-task'){const title=document.querySelector('#newTaskInput')?.value.trim();if(title){tasks.unshift({id:'t'+Date.now(),title,status:'todo',priority:'p2',due:'',tags:[],desc:'',note:null});state.modal=null;state.view='tasks';state.detail=null}}render()});
document.addEventListener('input',e=>{if(e.target.id==='noteSearch'){const pos=e.target.selectionStart;state.notesQuery=e.target.value;render();let el=document.querySelector('#noteSearch');el?.focus();el?.setSelectionRange(pos,pos)}if(e.target.id==='taskSearch'){const pos=e.target.selectionStart;state.taskQuery=e.target.value;render();let el=document.querySelector('#taskSearch');el?.focus();el?.setSelectionRange(pos,pos)}if(e.target.id==='globalSearchInput'){state.search=e.target.value;let c=document.querySelector('.modal-options');if(c)c.innerHTML=searchResults()}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.modal='search';render();document.querySelector('#globalSearchInput')?.focus()}if(e.key==='Escape'&&state.modal){state.modal=null;render()}if(e.key==='Enter'&&e.target.id==='newTaskInput'){document.querySelector('[data-action="create-task"]')?.click()}});
render();
